  &reftitle.examples;



    Пример изменения размера изображения методом Imagick::adaptiveResizeImage


     Пример слегка уменьшит исходное изображение до типичного для веба размера.



<?php

header('Content-type: image/jpeg');

$image = new Imagick('image.jpg');
$image->adaptiveResizeImage(1024, 768);

echo $image;
